/// Decode-then-encode by type name. Used only by the shared conformance runner.
pub fn conformance_round_trip(type_name: &str, value: &Value) -> Option<Result<Value, DecodeError>> {
    match type_name {
        "AdapterRef" => Some(decode_adapter_ref(value, "$").map(|decoded| encode_adapter_ref(&decoded))),
        "SlotTarget" => Some(decode_slot_target(value, "$").map(|decoded| encode_slot_target(&decoded))),
        "InstanceId" => Some(decode_instance_id(value, "$").map(|decoded| encode_instance_id(&decoded))),
        "InstanceStaleReason" => Some(decode_instance_stale_reason(value, "$").map(|decoded| encode_instance_stale_reason(&decoded))),
        "FaultPhase" => Some(decode_fault_phase(value, "$").map(|decoded| encode_fault_phase(&decoded))),
        "AdaptersRequest" => Some(decode_adapters_request(value, "$").map(|decoded| encode_adapters_request(&decoded))),
        "AdaptersResult" => Some(decode_adapters_result(value, "$").map(|decoded| encode_adapters_result(&decoded))),
        "AdaptersFact" => Some(decode_adapters_fact(value, "$").map(|decoded| encode_adapters_fact(&decoded))),
        _ => None,
    }
}
